// Netlify может прислать поля формы либо прямо в body, либо вложенными в body.data.
const body = $input.first().json.body || $input.first().json;
const data = body.data || body;

function pick(...keys) {
  for (const k of keys) {
    const v = data[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return String(v).trim();
    }
  }
  return '';
}

const name = pick('name', 'имя', 'full_name', 'fullname') || '—';
const company = pick('company', 'компания', 'organization') || '—';
const email = pick('email', 'почта');
const phone = pick('phone', 'телефон', 'tel');
const message = pick('message', 'сообщение', 'comment', 'текст');

const channelParts = [];
if (email) channelParts.push('Email: ' + email);
if (phone) channelParts.push('Тел.: ' + phone);
const channel = channelParts.length ? channelParts.join(', ') : '—';

return [{
  json: {
    token: 'YOUR_WEBHOOK_TOKEN',
    source: 'netlify',
    name,
    company,
    channel,
    message: message.slice(0, 300)
  }
}];

